/// <summary>
/// Extension class for table <c>GUPItemBasePrice</c>
/// </summary>
[ExtensionOf(tableStr(GUPItemBasePrice))]
public final class METGUPItemBasePrice_Extension
{
}

Method.Source:
    /// <summary>
    /// Initialise table buffer from GUPItemBasePriceSim table buffer 
    /// </summary>
    /// <param name = "_itemBasePriceSim">GUPItemBasePriceSim buffer</param>
    public void initFromGUPItemBasePriceSim(GUPItemBasePriceSim _itemBasePriceSim)
    {
        next initFromGUPItemBasePriceSim(_itemBasePriceSim);

        this.METVendClaimEnabled = _itemBasePriceSim.METVendClaimEnabled;
    }

    /// <summary>
    /// CB434, Initialise and create InventItemPrice based on the GUPItemBasePriceRecord
    /// </summary>
    public void inventItemPriceCreation()
    {
        InventItemPrice             inventItemPrice;
        GUPParameters               gupParameters = GUPParameters::find();

        inventItemPrice.clear();
        inventItemPrice.ItemId              = this.ItemId;
        inventItemPrice.initFromInventTableModule(InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent));
        inventItemPrice.VersionId           = gupParameters.METCostingVersionId;
        inventItemPrice.initFromCostingVersion();
        inventItemPrice.InventDimId         = InventTable::priceInventDimId(this.ItemId, this.InventDimId);
        inventItemPrice.PriceType           = CostingVersionPriceType::Cost;
        inventItemPrice.PriceQty            = 1;
        inventItemPrice.PriceUnit           = 1;
        inventItemPrice.Markup              = 0;
        inventItemPrice.Price               = this.Price;
        inventItemPrice.PriceCalcId         = this.PriceCalcId;
        inventItemPrice.ActivationDate      = this.FromDate;
        inventItemPrice.LastPriceUniquenessAllowance = newGuid();
        inventItemPrice.insert();

        // Create the costGroupRollup records
        InventItemCostGroupRollup inventItemCostGroupRollup;
        inventItemCostGroupRollup.initFromInventItemPrice(inventItemPrice);
        inventItemCostGroupRollup.InventItemPriceRefRecId = inventItemPrice.RecId;
        inventItemCostGroupRollup.insert();
    }
